import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFileSync} from "node:fs";
import {gzipSync,gunzipSync} from "node:zlib";
import {CoreCaller,list,u8,result} from "../../../../scripts/current-core-value-codec-v3.mjs";
const [root,manifestPin,artifactPin]=process.argv.slice(2);
assert.ok(root && /^[0-9a-f]{64}$/.test(manifestPin??"") && /^[0-9a-f]{64}$/.test(artifactPin??""));
const hash=x=>createHash("sha256").update(x).digest("hex");
const manifestBytes=readFileSync(root+"/lib.json"), manifest=JSON.parse(manifestBytes), artifact=readFileSync(root+"/artifact.wasm");
assert.equal(hash(manifestBytes),manifestPin); assert.equal(hash(artifact),artifactPin); assert.equal(manifest.artifact.sha256,artifactPin);
const abi=JSON.parse(readFileSync(root+"/core-abi.json")); assert.equal(abi.artifact_sha256,artifactPin);
const caller=new CoreCaller(new WebAssembly.Module(artifact),abi);
const errors=["input-too-large","output-too-large","invalid-stream","internal-failure"], output=result(list(u8),errors);
const size=17*1024*1024+1, input=Buffer.allocUnsafe(size);
for(let i=0;i<size;i++) input[i]=(i*73+(i>>>11))&255;
const reference=gzipSync(input), decoded=caller.call("decompress",[list(u8)],[Array.from(reference)],output);
assert.equal(decoded.tag,"ok"); assert.deepEqual(Buffer.from(decoded.value),input);
const compressed=caller.call("compress",[list(u8)],[Array.from(input)],output);
assert.equal(compressed.tag,"ok"); assert.deepEqual(gunzipSync(Buffer.from(compressed.value)),input);
assert.equal(caller.call("decompress",[list(u8)],[[0,1,2]],output).tag,"err");
const again=caller.call("decompress",[list(u8)],[Array.from(gzipSync(Buffer.from("fresh")))],output);
assert.equal(again.tag,"ok"); assert.equal(Buffer.from(again.value).toString(),"fresh");
console.log(JSON.stringify({accepted:true,installed_fixture:true,manifest_sha256:manifestPin,artifact_sha256:artifactPin,input_bytes:size,input_sha256:hash(input),cross_implementation:true,invalid_then_same_instance_recovery:true,formal_release:false}));
